``` java
@RunWith(JUnit5.class)
public class DemoTestEngine implements TestEngine {
    @Override
    public String getId() {
        return "demo";
    }

    @Override
    public TestDescriptor discover(EngineDiscoveryRequest discoveryRequest, UniqueId uniqueId) {
        EngineDescriptor engineDescriptor = new EngineDescriptor(uniqueId.append("engine", "demo"), "demo");
        engineDescriptor.addChild(new RootTestDescriptor(engineDescriptor.getUniqueId().append("root", "0"), "0"));
        return engineDescriptor;
    }

    @Override
    public void execute(ExecutionRequest request) {
        EngineExecutionListener engineExecutionListener = request.getEngineExecutionListener();
        TestDescriptor root = request.getRootTestDescriptor();
        TestDescriptor child = new TestTestDescriptor(root.getUniqueId().append("container", "1"), "1");
        root.addChild(child);
        engineExecutionListener.dynamicTestRegistered(child);
        engineExecutionListener.executionStarted(child);
        engineExecutionListener.executionFinished(child, TestExecutionResult.successful());
        TestDescriptor grandchild = new TestTestDescriptor(child.getUniqueId().append("test", "2"), "2");
        child.addChild(grandchild);
        engineExecutionListener.dynamicTestRegistered(grandchild);
        engineExecutionListener.executionStarted(grandchild);
        engineExecutionListener.executionFinished(grandchild, TestExecutionResult.successful());
    }

    abstract static class AbstractDisplayNamedTestDescriptor extends AbstractTestDescriptor {
        private final String displayName;

        AbstractDisplayNamedTestDescriptor(UniqueId uniqueId, String displayName) {
            super(uniqueId);
            this.displayName = displayName;
        }

        @Override
        public String getDisplayName() {
            return displayName;
        }
    }

    static class RootTestDescriptor extends AbstractDisplayNamedTestDescriptor {
        RootTestDescriptor(UniqueId uniqueId, String displayName) {
            super(uniqueId,displayName);
        }

        @Override
        public boolean isContainer() {
            return true;
        }

        @Override
        public boolean isTest() {
            return false;
        }

        @Override
        public boolean hasTests() {
            return true;
        }
    }

    static class ContainerTestDescriptor extends AbstractDisplayNamedTestDescriptor {
        ContainerTestDescriptor(UniqueId uniqueId, String displayName) {
            super(uniqueId, displayName);
        }

        @Override
        public boolean isContainer() {
            return true;
        }

        @Override
        public boolean isTest() {
            return false;
        }
    }

    static class TestTestDescriptor extends AbstractDisplayNamedTestDescriptor {
        TestTestDescriptor(UniqueId uniqueId, String displayName) {
            super(uniqueId, displayName);
        }

        @Override
        public boolean isContainer() {
            return false;
        }

        @Override
        public boolean isTest() {
            return true;
        }
    }
}
